    {
      size_t _k;
      for (_k = 0; _k < 16; ++_k) {
        aggregate_sums_u16_madd(anchor, sum);
      }
    }
    (void)in; (void)out;  /* sum-only: no zero-fill of out */
    break;

  case 1:
    __SIMD_fastunpack1_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 2:
    __SIMD_fastunpack2_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

