    break;

  case 6:
    __SIMD_fastunpack6_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 7:
    __SIMD_fastunpack7_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 8:
    __SIMD_fastunpack8_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 9:
    __SIMD_fastunpack9_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 10:
    __SIMD_fastunpack10_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 11:
    __SIMD_fastunpack11_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 12:
    __SIMD_fastunpack12_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 13:
    __SIMD_fastunpack13_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 14:
    __SIMD_fastunpack14_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 15:
    __SIMD_fastunpack15_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

  case 16:
    __SIMD_fastunpack16_16_corrected_uniform_madd_w128(in, out, sum, anchor);
    break;

