    __SIMD_fastunpack3_16_cscalar0_madd_w128(in, out, sum, a_block);
    break;

  case 4:
    __SIMD_fastunpack4_16_cscalar0_madd_w128(in, out, sum, a_block);
    break;

  case 5:
    __SIMD_fastunpack5_16_cscalar0_madd_w128(in, out, sum, a_block);
