    (void)in; (void)out;  /* sum-only: no zero-fill of out */
    break;

  case 1:
    __SIMD_fastunpack1_16_cscalar2_madd_w128(in, out, sum, a_block);
    break;

  case 2:
    __SIMD_fastunpack2_16_cscalar2_madd_w128(in, out, sum, a_block);
    break;

  case 3:
    __SIMD_fastunpack3_16_cscalar2_madd_w128(in, out, sum, a_block);
    break;

  case 4:
