    break;

  case 6:
    __SIMD_fastunpack6_16_chalf_shuf_noagg_w128(in, out, sum, a_block);
    break;

  case 7:
    __SIMD_fastunpack7_16_chalf_shuf_noagg_w128(in, out, sum, a_block);
    break;

  case 8:
    __SIMD_fastunpack8_16_chalf_shuf_noagg_w128(in, out, sum, a_block);
